import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DC2M1AAK.js";const k=JSON.parse('{"title":"Embedding in your app: the agent-token exchange, seats and caps","description":"","frontmatter":{},"headers":[],"relativePath":"components/sdk-auth.md","filePath":"components/sdk-auth.md"}'),n={name:"components/sdk-auth.md"};function o(r,e,d,h,p,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="embedding-in-your-app-the-agent-token-exchange-seats-and-caps" tabindex="-1">Embedding in your app: the agent-token exchange, seats and caps <a class="header-anchor" href="#embedding-in-your-app-the-agent-token-exchange-seats-and-caps" aria-label="Permalink to &quot;Embedding in your app: the agent-token exchange, seats and caps&quot;">​</a></h1><blockquote><p>Settled design from a production integration (a mobile app hosting the widget in a web view with native bridges for photos and voice). Built into <code>packages/gateway/src/auth.ts</code>.</p></blockquote><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>Your app authenticates the user</strong> against your auth service. Nothing in the SDK or the gateway logs a user in.</li><li><strong>Your broad access token never enters a web view.</strong> The native side exchanges it for a short-lived AGENT TOKEN that only the agent API accepts.</li><li><strong>Identity is verified once, at exchange, by calling your auth service — and fails closed.</strong></li><li><strong>A seat is checked at exchange and a cap is enforced before every turn.</strong></li><li><strong>A session id is an id, not a credential.</strong> Every session endpoint checks the owner.</li></ol><h2 id="the-three-credentials" tabindex="-1">The three credentials <a class="header-anchor" href="#the-three-credentials" aria-label="Permalink to &quot;The three credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Credential</th><th>Held by</th><th>Lifetime</th><th>Goes to</th></tr></thead><tbody><tr><td>Your access token (+ refresh)</td><td>the native app only</td><td>yours</td><td><code>POST /api/auth/exchange</code> only</td></tr><tr><td>App key (<code>X-Agent-App-Key</code>)</td><td>the app build (one per platform/tenant)</td><td>until rotated</td><td>every gateway call; an identifier, not a secret</td></tr><tr><td>Agent token</td><td>the web view&#39;s JS memory + the native side</td><td>15 min, renewed by the native side</td><td>every <code>/api/*</code> call</td></tr></tbody></table><h2 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user ──login──▶ your auth service ──▶ access token held by the app</span></span>
<span class="line"><span>app  ── POST /api/auth/exchange [X-Agent-App-Key, Bearer &lt;access token&gt;] ──▶ gateway</span></span>
<span class="line"><span>gateway: app key → tenant ; GET AGENT_AUTH_VERIFY_URL (strict) → sub, name, firm ;</span></span>
<span class="line"><span>         GET AGENT_ENTITLEMENT_URL/{firm}/{sub} → seat + cap ; vault the access token ;</span></span>
<span class="line"><span>         mint {sub, firm_id, tenant, seat, jti, exp}</span></span>
<span class="line"><span>app  ◀── { agent_token, expires_in: 900, user, firm, seat, cap } ──</span></span>
<span class="line"><span>web view ── widget calls opts.token() (async) → agent token ──▶ every /api/* call</span></span>
<span class="line"><span>gateway: verify signature, exp, jti not revoked → bind the session&#39;s owner = sub →</span></span>
<span class="line"><span>         per tool call, attach the VAULTED access token (acts as the user; your API enforces permissions)</span></span>
<span class="line"><span>app: re-exchange at expires_in − 60 s, or on 401 token_expired, with a fresh access token</span></span></code></pre></div><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><ul><li><code>POST /api/auth/exchange</code> → 200 <code>{agent_token, expires_in, user, firm, seat, cap}</code>; 401 <code>invalid_token</code> / <code>invalid_app_key</code>; 403 <code>no_seat</code> (<code>seat: none|suspended</code>) / <code>firm_inactive</code>; 503 <code>auth_unavailable</code> / <code>entitlement_unavailable</code>. Disabled (501) without <code>AGENT_TOKEN_SECRET</code>.</li><li><code>POST /api/auth/logout</code> — revokes the <code>jti</code>, drops the vaulted token.</li><li>A removed user keeps chatting for at most the token&#39;s lifetime; wire your admin backend to revoke on removal (<code>revokeUser</code>) for immediate effect.</li></ul><h2 id="entitlement-contract" tabindex="-1">Entitlement contract <a class="header-anchor" href="#entitlement-contract" aria-label="Permalink to &quot;Entitlement contract&quot;">​</a></h2><p><code>GET AGENT_ENTITLEMENT_URL/{firm_id}/{sub}</code> with <code>AGENT_ENTITLEMENT_KEY</code> →</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;seat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;active|none|suspended&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;plan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pro&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cap&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;credits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;period&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;month&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;resets_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-11-01T00:00:00+05:30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;firm_status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;active|past_due&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Decided defaults: unseated users are refused at exchange (no trial); caps per seat per calendar month with a daily ceiling of 10% of the month; the user sees a percent; over cap ⇒ 429 <code>usage_cap</code> with <code>scope</code> and <code>resets_at</code>. Account identity for metering: <code>account_id = &lt;tenant&gt;:&lt;sub&gt;</code>, parent = firm — opaque, so it can move to another identity platform.</p><h2 id="expiry-mid-turn" tabindex="-1">Expiry mid-turn <a class="header-anchor" href="#expiry-mid-turn" aria-label="Permalink to &quot;Expiry mid-turn&quot;">​</a></h2><p>If your API answers 401 inside a turn, the gateway ends the turn with <code>token_expired</code>, <code>retryable: true</code>; the native side re-exchanges and the client resends the message once. Reads are harmless; the one write is idempotent (session + draft fingerprint).</p><h2 id="the-web-view-host-what-the-first-integration-measured" tabindex="-1">The web-view host (what the first integration measured) <a class="header-anchor" href="#the-web-view-host-what-the-first-integration-measured" aria-label="Permalink to &quot;The web-view host (what the first integration measured)&quot;">​</a></h2><p>A web-view host of the widget was GO on Android: tap-to-interactive 0.7–0.9 s in a warm process, ~2.6 s on a first-ever web view in an install, +80–90 MB; keep the widget script compressed and versioned, give the host page a CSP and a navigation allowlist, and bridge photo picking and the microphone natively. The widget&#39;s <code>opts.token</code> accepts an async function so a renewed token applies on the next request.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/SDK-AUTH.md">docs/SDK-AUTH.md</a> — edit it there; the site mirrors the repository.</small></p>`,20)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
